import {Dialog} from '@primer/react/experimental'
import {Banner} from '@primer/react'
import {useCallback, useState} from 'react'
import {useConfirmCopilotPlanChange} from '../../hooks/use-confirm-copilot-plan-change'
import {useNavigate} from '@github-ui/use-navigate'
import styles from './CopilotOrganizationDowngradePlanDialog.module.css'
import {clsx} from 'clsx'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {capitalizePlan} from '../../utils/string-utils'

interface CopilotOrganizationDowngradePlanDialogProps {
  oldPlan: string
  newPlan: string
  orgId: number
  closeDialog: () => void
}

export const CopilotOrganizationDowngradePlanDialog = ({
  oldPlan,
  newPlan,
  orgId,
  closeDialog,
}: CopilotOrganizationDowngradePlanDialogProps) => {
  const navigate = useNavigate()
  const {basePath} = useNavigation()

  const handleCloseDialog = useCallback(() => {
    closeDialog()
  }, [closeDialog])
  const [showPlanChangeError, setShowPlanChangeError] = useState(false)

  const handleConfirmClick = useConfirmCopilotPlanChange(
    newPlan,
    orgId,
    basePath,
    () => {
      handleCloseDialog()
      navigate(`${basePath}/licensing/copilot?tab=organizations`)
    },
    () => {
      setShowPlanChangeError(true)
    },
  )

  return (
    <Dialog
      className={clsx(styles.downgradeConfirmationDialog)}
      onClose={handleCloseDialog}
      title={newPlan === 'disabled' ? 'Disable organization access' : 'Downgrade organization access'}
      footerButtons={[
        {buttonType: 'default', content: 'Cancel', onClick: handleCloseDialog},
        {
          buttonType: 'danger',
          content: newPlan === 'disabled' ? 'Remove access' : 'Downgrade licenses',
          onClick: handleConfirmClick,
        },
      ]}
    >
      {showPlanChangeError && (
        <Banner
          title="Copilot plan change error"
          hideTitle
          variant="critical"
          onDismiss={() => setShowPlanChangeError(false)}
          className="tmp-mb-3"
          data-testid="copilot-plan-change-error-banner"
        >
          {'An error occurred while updating the Copilot plan for this organization.'}
        </Banner>
      )}
      <div data-testid="copilot-downgrade-confirm-dialog">
        {newPlan === 'disabled' ? (
          <>
            Do you want to disable Copilot for this organization? This will:
            <ul className="mt-2 tmp-ml-3 px-2">
              <li>
                Remove Copilot {capitalizePlan(oldPlan)} licenses. Users will lose access to Copilot at the end of the
                billing cycle.
              </li>
              <li>Organization access will change to &ldquo;Specific organizations&rdquo; if set to enable all.</li>
            </ul>
          </>
        ) : (
          <>Do you want to downgrade this organization to Copilot {capitalizePlan(newPlan)}?</>
        )}

        {newPlan !== 'disabled' && (
          <p className={'color-fg-muted tmp-mt-4'}>
            {`Users will lose access to Copilot ${capitalizePlan(
              oldPlan,
            )} and be downgraded to Copilot ${capitalizePlan(newPlan)} at the end of the current billing cycle.`}
          </p>
        )}
      </div>
    </Dialog>
  )
}
