import {Dialog, IconButton, Spinner} from '@primer/react'
import {GlobeIcon, PeopleIcon, OrganizationIcon, XIcon} from '@primer/octicons-react'
import styles from './CopilotMemberLicenseSummaryDialog.module.css'
import type {Member, Assignment} from '../../types'
import {useEffect, useState} from 'react'
import {CopilotUserChangeAccessDialog} from './CopilotUserChangeAccessDialog'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {Blankslate} from '@primer/react/experimental'

export interface CopilotMemberLicenseSummaryDialogProps {
  user: Member
  onClose: () => void
}

export function CopilotMemberLicenseSummaryDialog(props: CopilotMemberLicenseSummaryDialogProps) {
  const [showConfirmationDialog, setShowConfirmationDialog] = useState(false)
  const {basePath} = useNavigation()
  const [assignments, setAssignments] = useState<Assignment[]>([])
  const [loading, setLoading] = useState<boolean>(true)

  useEffect(() => {
    async function fetchData() {
      try {
        const response = await verifiedFetch(`${basePath}/licensing/all_licenses_for_user/${props.user.id}`)
        if (response.ok) {
          const result = await response.json()
          setAssignments(result.assignments)
        }
      } catch {
        setAssignments([])
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [basePath, props.user.id])

  function renderIcon(licenseOwnerType: Assignment['ownerDisplayType']) {
    switch (licenseOwnerType) {
      case 'Business':
        return <GlobeIcon size={16} aria-label="Enterprise" />
      case 'Organization':
        return <OrganizationIcon size={16} aria-label="Organization" />
      case 'BusinessTeam':
        /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        return <PeopleIcon size={16} aria-label="Enterprise Team" />
    }
  }

  function formatDate(dateString: string) {
    const endDate = new Date(dateString)
    return endDate.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
    })
  }
  let mainContent

  if (loading) {
    mainContent = (
      <Blankslate>
        <Blankslate.Description>
          <Spinner size="medium" />
        </Blankslate.Description>
      </Blankslate>
    )
  } else {
    if (assignments.length === 0) {
      mainContent = (
        <Blankslate>
          <Blankslate.Description>
            There was an error retrieving the license assignments for this user
          </Blankslate.Description>
        </Blankslate>
      )
    } else {
      mainContent = (
        <table style={{width: '100%'}}>
          <thead>
            <tr>
              <th className={styles.thBottom} scope="col">
                Source
              </th>
              <th className={styles.thBottom} scope="col">
                License
              </th>
              <th className={styles.thBottom} scope="col">
                Status
              </th>
              <th className={styles.thBottom} scope="col">
                <span className="sr-only">Actions</span>
              </th>
            </tr>
          </thead>
          <tbody>
            {assignments.map(license => (
              <tr key={license.id} data-testid={`license-information-for-${license.id}`} className={styles.trBottom}>
                <td className={styles.tdBottom}>
                  {renderIcon(license.ownerDisplayType)}
                  <a href={license.ownerUrl} style={{marginLeft: '8px'}}>
                    {license.ownerDisplayName}
                  </a>
                </td>
                <td className={styles.tdBottom}>
                  Copilot
                  <span>{license.planType === 'business' ? ' Business' : ' Enterprise'}</span>
                </td>
                {license.expirationDate ? (
                  <td className={styles.tdBottom}>
                    <span>{`Expires ${formatDate(license.expirationDate)}`}</span>
                  </td>
                ) : (
                  <td className={styles.activeLicense}>
                    <span>Active</span>
                  </td>
                )}
                <td className={styles.tdBottom}>
                  {license.ownerDisplayType === 'Business' && license.expirationDate === null ? (
                    <IconButton
                      data-testid={`remove-license-button-${license.id}`}
                      icon={XIcon}
                      aria-label={`Remove license from ${license.ownerDisplayName}`}
                      variant="invisible"
                      className={styles.removeButton}
                      onClick={() => {
                        setShowConfirmationDialog(true)
                      }}
                    />
                  ) : null}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )
    }
  }

  return (
    <>
      <Dialog
        title={`Copilot license assignments for ${props.user.name}`}
        subtitle={`Members can receive Copilot access through membership in different entities, such as teams, organizations,
              or directly through the enterprise`}
        onClose={props.onClose}
        className={styles.dialog}
      >
        <div data-testid={`license-assignment-summary-for-${props.user.id}`}>{mainContent}</div>
      </Dialog>

      {showConfirmationDialog && (
        <CopilotUserChangeAccessDialog
          users={[props.user.id]}
          downgrade
          onClose={() => {
            setShowConfirmationDialog(false)
          }}
        />
      )}
    </>
  )
}
