import type {Sku} from '../copilot-types'
import {Stack} from '@primer/react'
import {clsx} from 'clsx'
import styles from './CopilotUsageSummary.module.css'

import {CopilotUsageSummaryItem} from './CopilotUsageSummaryItem'
import {UsageHint} from './UsageHint'
import {UsageSummary} from './UsageSummary'

export interface CopilotUsageSummaryProps {
  skus: Sku[]
  headingLevel?: 'h2' | 'h3'
}

export function CopilotUsageSummary({skus, headingLevel}: CopilotUsageSummaryProps) {
  const description =
    skus.length === 1 && skus[0]
      ? `Unique licenses assigned for Copilot ${skus[0].sku.charAt(0).toUpperCase() + skus[0].sku.slice(1)}.`
      : 'Unique licenses assigned for Copilot Business and Copilot Enterprise.'

  return (
    <UsageSummary
      title="Consumed licenses"
      headingAs={headingLevel}
      usageHint={
        <UsageHint
          title="Consumed licenses"
          label="About Copilot consumed licenses"
          description={description}
          learnMoreUrl="https://docs.github.com/en/copilot/about-github-copilot/subscription-plans-for-github-copilot"
        />
      }
    >
      <Stack direction="horizontal" gap="condensed" padding="none" className={clsx(styles.childrenWrapper)}>
        {skus.map(sku => (
          <CopilotUsageSummaryItem key={sku.sku} {...sku} />
        ))}
      </Stack>
    </UsageSummary>
  )
}
