import {clsx} from 'clsx'
import {ListView} from '@github-ui/list-view'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemActionBar} from '@github-ui/list-view/ListItemActionBar'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemDescriptionItem} from '@github-ui/list-view/ListItemDescriptionItem'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import type {Member} from '../../types'
import styles from './CopilotAllMembersAccessList.module.css'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {ActionList, Label, Pagination, Spinner} from '@primer/react'
import {CopilotUserChangeAccessDialog} from './CopilotUserChangeAccessDialog'
import {useState} from 'react'
import {useEnterpriseCopilotAccessFetch} from '../../hooks/use-enterprise-copilot-access-fetch'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {Blankslate} from '@primer/react/experimental'
import {CopilotMemberLicenseSummaryDialog} from './CopilotMemberLicenseSummaryDialog'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {MemoryExportsDialog, memoryExportUrlWithTargetUser} from '@github-ui/copilot-memory-exports'
import {MemoryAdminDeleteDialog} from '@github-ui/copilot-for-business/components/MemoryAdminDeleteDialog'
import pluralize from 'pluralize'

export interface CopilotAllMembersAccessListProps {
  searchQuery?: string
  isTrial?: boolean
  memoryExportUrl?: string | null
  memoryAdminDeleteUrl?: string | null
}

export function CopilotAllMembersAccessList(props: CopilotAllMembersAccessListProps) {
  const {basePath, slug} = useNavigation()
  const [selectedUserForDialog, setSelectedUserForDialog] = useState<number | number[] | null>(null)
  const [selectedUserForSummary, setSelectedUserForSummary] = useState<Member | null>(null)
  const [selectedUserForMemoryExport, setSelectedUserForMemoryExport] = useState<Member | null>(null)
  const [selectedUserForMemoryDelete, setSelectedUserForMemoryDelete] = useState<Member | null>(null)

  let mainContent
  let pagination
  let showBorder = true

  // Server-side pagination state
  const [currentPage, setCurrentPage] = useState(1)
  const pageSize = 20

  // Fetch users with Copilot access (server paginated)
  const {
    results: users,
    loading,
    isEmpty,
    fetchCompleted,
    totalCount,
  } = useEnterpriseCopilotAccessFetch<'all_members'>({
    basePath,
    searchQuery: props.searchQuery || '',
    searchType: 'all_members',
    withAccess: true,
    page: currentPage,
  })

  const handleCloseLicenseRemovalDialog = () => {
    setSelectedUserForDialog(null)
  }

  const handleViewLicenseSummary = (user: Member) => {
    setSelectedUserForSummary(user)
  }

  const handleCloseSummary = () => {
    setSelectedUserForSummary(null)
  }

  const handleExportMemories = (user: Member) => {
    setSelectedUserForMemoryExport(user)
  }

  const handleCloseMemoryExportDialog = () => {
    setSelectedUserForMemoryExport(null)
  }

  const handleDeleteMemories = (user: Member) => {
    setSelectedUserForMemoryDelete(user)
  }

  const handleCloseMemoryDeleteDialog = () => {
    setSelectedUserForMemoryDelete(null)
  }

  const selectedUserMemoryExportUrl =
    selectedUserForMemoryExport && props.memoryExportUrl
      ? memoryExportUrlWithTargetUser(props.memoryExportUrl, selectedUserForMemoryExport.id)
      : null
  const selectedUserMemoryExportLogin = selectedUserForMemoryExport?.login
  const selectedUserMemoryDeleteUrl =
    selectedUserForMemoryDelete && props.memoryAdminDeleteUrl
      ? memoryExportUrlWithTargetUser(props.memoryAdminDeleteUrl, selectedUserForMemoryDelete.id)
      : null
  const selectedUserMemoryDeleteLogin = selectedUserForMemoryDelete?.login
  // Calculate total pages from server totalCount
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize))

  // Pagination handler
  const navigateToPage = (page: number) => {
    setCurrentPage(page)
  }

  if (loading) {
    mainContent = <Spinner size="medium" />
  } else {
    if (fetchCompleted) {
      if (isEmpty) {
        mainContent = (
          <Blankslate>
            <Blankslate.Heading>No individual licenses</Blankslate.Heading>
            <Blankslate.Description>
              Enterprise members who have been granted Copilot Business will be visible here
            </Blankslate.Description>
          </Blankslate>
        )
      } else {
        showBorder = false
        mainContent = (
          <ListView
            title={'Users'}
            className="border border-muted rounded-2"
            data-testid="licensing-copilot-all-members-access-list-view"
            metadata={<ListViewMetadata title={pluralize('member', totalCount, true)} />}
          >
            {users.map((user: Member) => (
              <ListItem
                key={user.id}
                title={
                  <ListItemTitle
                    value={user.login}
                    href={user.userUrl}
                    trailingBadges={
                      user.licenseExpirationDate
                        ? [
                            <Label key="expiration" variant="attention" size="small">
                              Expires on {user.licenseExpirationDate}
                            </Label>,
                          ]
                        : undefined
                    }
                  />
                }
                secondaryActions={
                  <ListItemActionBar
                    label="user license options"
                    staticMenuActions={[
                      {
                        key: 'view-license-assignments',
                        render: () => (
                          <div style={{maxWidth: '280px'}}>
                            <ActionList.Item
                              data-testid={`view-license-assignments-${user.id}`}
                              onSelect={() => handleViewLicenseSummary(user)}
                            >
                              <span className={'color-fg-default text-bold'}>View license assignments</span>
                              <p className={'color-fg-muted mt-1'}>
                                See license type and other sources assigned for this user
                              </p>
                            </ActionList.Item>
                          </div>
                        ),
                      },
                      ...(props.memoryExportUrl
                        ? [
                            {
                              key: 'export-copilot-memories',
                              render: () => (
                                <div style={{maxWidth: '280px'}}>
                                  <ActionList.Item
                                    data-testid={`export-copilot-memories-${user.id}`}
                                    onSelect={() => handleExportMemories(user)}
                                  >
                                    <span className={'color-fg-default text-bold'}>Export Copilot memories</span>
                                    <p className={'color-fg-muted mt-1'}>
                                      Download user-scoped Copilot memories billed to this enterprise
                                    </p>
                                  </ActionList.Item>
                                </div>
                              ),
                            },
                          ]
                        : []),
                      ...(props.memoryAdminDeleteUrl
                        ? [
                            {
                              key: 'delete-copilot-memories',
                              render: () => (
                                <div style={{maxWidth: '280px'}}>
                                  <ActionList.Item
                                    variant="danger"
                                    data-testid={`delete-copilot-memories-${user.id}`}
                                    onSelect={() => handleDeleteMemories(user)}
                                  >
                                    <span className={'color-fg-default text-bold'}>Delete Copilot memories</span>
                                    <p className={'color-fg-muted mt-1'}>
                                      Permanently delete user-scoped Copilot memories billed to this enterprise
                                    </p>
                                  </ActionList.Item>
                                </div>
                              ),
                            },
                          ]
                        : []),
                    ]}
                  />
                }
              >
                <ListItemLeadingContent>
                  <ListItemLeadingVisual>
                    <GitHubAvatar src={user.avatarUrl} size={16} />
                  </ListItemLeadingVisual>
                </ListItemLeadingContent>

                <ListItemMainContent>
                  <ListItemDescription>
                    <ListItemDescriptionItem>{user.name}</ListItemDescriptionItem>
                  </ListItemDescription>
                </ListItemMainContent>
              </ListItem>
            ))}
          </ListView>
        )

        if (totalPages > 1) {
          pagination = (
            <div className="tmp-mt-3 d-flex flex-justify-center">
              <Pagination
                currentPage={currentPage}
                pageCount={totalPages}
                onPageChange={(_, newPage) => navigateToPage(newPage)}
              />
            </div>
          )
        }
      }
    }
  }
  return (
    <>
      <div className={clsx(showBorder && styles.emptyContainer, loading && styles.spinnerContainer)}>
        {mainContent}
        {pagination}
        {selectedUserForDialog !== null && (
          <CopilotUserChangeAccessDialog
            users={Array.isArray(selectedUserForDialog) ? selectedUserForDialog : [selectedUserForDialog]}
            downgrade
            onClose={handleCloseLicenseRemovalDialog}
            isTrial={props.isTrial}
          />
        )}
        {selectedUserForSummary !== null && (
          <CopilotMemberLicenseSummaryDialog user={selectedUserForSummary} onClose={handleCloseSummary} />
        )}
        {selectedUserForMemoryExport !== null && (
          <MemoryExportsDialog
            isOpen
            onClose={handleCloseMemoryExportDialog}
            entityName={slug}
            entityType="enterprise"
            memoryExportUrl={selectedUserMemoryExportUrl}
            targetUserLogin={selectedUserMemoryExportLogin}
          />
        )}
        {selectedUserForMemoryDelete !== null && (
          <MemoryAdminDeleteDialog
            isOpen
            onClose={handleCloseMemoryDeleteDialog}
            entityName={slug}
            memoryDeleteUrl={selectedUserMemoryDeleteUrl}
            targetUserLogin={selectedUserMemoryDeleteLogin}
          />
        )}
      </div>
    </>
  )
}
