import {announce} from '@github-ui/aria-live'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {DownloadIcon} from '@primer/octicons-react'
import {Banner, Button, Spinner} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useEffect, useRef, useState} from 'react'

type MemoryExportResponse = {
  state?: 'none' | 'queued' | 'started' | 'success' | 'error'
  jobStatusUrl?: string
  downloadExportUrl?: string
  error?: string
}

type MemoryExportNotification = {
  message: string
  variant: 'critical' | 'warning'
}

export type MemoryExportsEntityType = 'organization' | 'enterprise'

type MemoryExportsDialogProps = {
  isOpen: boolean
  onClose: () => void
  /**
   * The display name of the entity the export is scoped to (e.g. an organization
   * or enterprise name). Shown in the dialog body copy.
   */
  entityName: string
  /**
   * What kind of entity owns the export. Drives the trailing noun in the
   * permission confirmation copy ("...users in this organization" vs
   * "...users in this enterprise"). Defaults to "organization".
   */
  entityType?: MemoryExportsEntityType
  memoryExportUrl?: string | null
  targetUserLogin?: string
}

const POLLING_INTERVAL_MS = 2_000
const MAX_POLLING_DURATION_MS = 15 * 60 * 1000
const MEMORY_EXPORT_GENERATION_ERROR_MESSAGE = "We couldn't generate your export. Please try again later."
const MEMORY_EXPORT_STATUS_ERROR_MESSAGE = "We couldn't check your export status. Please try again later."
const MEMORY_EXPORT_POLLING_TIMEOUT_MESSAGE =
  'This export is taking longer than expected. You can close this dialog and check again later.'

class MemoryExportPollingTimeoutError extends Error {
  constructor() {
    super(MEMORY_EXPORT_POLLING_TIMEOUT_MESSAGE)
    this.name = 'MemoryExportPollingTimeoutError'
  }
}

class MemoryExportPollingAbortError extends Error {
  constructor() {
    super('copilot_memory_admin_export_polling_aborted')
    this.name = 'MemoryExportPollingAbortError'
  }
}

function isAbortError(error: unknown): boolean {
  return (
    error instanceof MemoryExportPollingAbortError || (error instanceof DOMException && error.name === 'AbortError')
  )
}

async function wait(ms: number, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted) throw new MemoryExportPollingAbortError()

  return new Promise((resolve, reject) => {
    const abort = () => {
      clearTimeout(timeout)
      reject(new MemoryExportPollingAbortError())
    }
    const timeout = setTimeout(() => {
      signal?.removeEventListener('abort', abort)
      resolve()
    }, ms)
    signal?.addEventListener('abort', abort, {once: true})
  })
}

async function pollMemoryExportJob(
  url: string,
  startedAt = Date.now(),
  signal?: AbortSignal,
): Promise<MemoryExportResponse | null> {
  if (signal?.aborted) throw new MemoryExportPollingAbortError()

  if (Date.now() - startedAt >= MAX_POLLING_DURATION_MS) {
    throw new MemoryExportPollingTimeoutError()
  }

  const response = signal ? await verifiedFetch(url, {signal}) : await verifiedFetch(url)
  const data = await getMemoryExportResponse(response)

  if (response.status === 202) {
    await wait(POLLING_INTERVAL_MS, signal)
    return pollMemoryExportJob(url, startedAt, signal)
  }

  if (response.status > 399 || data?.error || data?.state === 'error') {
    throw new Error(MEMORY_EXPORT_GENERATION_ERROR_MESSAGE)
  }

  return data
}

function downloadMemoryExport(url: string): void {
  const link = document.createElement('a')
  link.href = url
  // Prevent Turbo from intercepting this anchor click. Without this, Turbo's turbo:click
  // handler calls event.preventDefault() and cancels both the browser navigation and its
  // own fetch, so the download silently never happens.
  link.setAttribute('data-turbo', 'false')
  link.hidden = true
  document.body.appendChild(link)
  link.click()
  link.remove()
}

export function memoryExportUrlWithTargetUser(
  memoryExportUrl: string | null | undefined,
  targetUserId: number,
): string | null {
  if (!memoryExportUrl) return null

  const [urlWithoutHash = '', hash] = memoryExportUrl.split('#', 2)
  const [path = '', query = ''] = urlWithoutHash.split('?', 2)
  const searchParams = new URLSearchParams(query)
  searchParams.set('target_user_id', String(targetUserId))
  const search = searchParams.toString()

  return `${path}${search ? `?${search}` : ''}${hash ? `#${hash}` : ''}`
}

async function getMemoryExportResponse(response: Response): Promise<MemoryExportResponse | null> {
  if (response.status === 204) return null

  return (await response.json()) as MemoryExportResponse
}

function notificationForError(error: unknown, fallbackMessage: string): MemoryExportNotification {
  if (error instanceof MemoryExportPollingTimeoutError) {
    return {message: MEMORY_EXPORT_POLLING_TIMEOUT_MESSAGE, variant: 'warning'}
  }

  return {message: fallbackMessage, variant: 'critical'}
}

export function MemoryExportsDialog({
  isOpen,
  onClose,
  entityName,
  entityType = 'organization',
  memoryExportUrl,
  targetUserLogin,
}: MemoryExportsDialogProps) {
  const [isCreatingExport, setIsCreatingExport] = useState(false)
  const [isWaitingForActiveExport, setIsWaitingForActiveExport] = useState(false)
  const [isCheckingActiveExport, setIsCheckingActiveExport] = useState(false)
  const [readyExportUrl, setReadyExportUrl] = useState<string | null>(null)
  const [notification, setNotification] = useState<MemoryExportNotification | null>(null)
  const dialogSessionIdRef = useRef(0)
  const requestIdRef = useRef(0)
  const requestAbortControllerRef = useRef<AbortController | null>(null)
  const isGeneratingExport = isCreatingExport || isWaitingForActiveExport
  const isConfirmButtonBusy = isCheckingActiveExport || isGeneratingExport
  const confirmButtonText = isCheckingActiveExport
    ? 'Checking export status...'
    : isGeneratingExport
      ? 'Generating report...'
      : 'Download memories'

  useEffect(() => {
    if (isCheckingActiveExport) {
      announce('Checking export status...')
    } else if (isGeneratingExport) {
      announce('Generating report...')
    }
  }, [isCheckingActiveExport, isGeneratingExport])

  useEffect(() => {
    if (notification) announce(notification.message)
  }, [notification])

  useEffect(() => {
    // Each time the dialog opens, bump the session id so any stale async
    // callbacks from a previous open are ignored.
    if (isOpen) {
      dialogSessionIdRef.current += 1
    }
  }, [isOpen])

  useEffect(() => {
    if (!isOpen || !memoryExportUrl) return

    let cancelled = false
    const abortController = new AbortController()

    const checkActiveExport = async () => {
      setReadyExportUrl(null)
      setNotification(null)
      setIsWaitingForActiveExport(false)
      setIsCheckingActiveExport(true)

      try {
        const response = await verifiedFetch(memoryExportUrl, {
          headers: {Accept: 'application/json'},
          signal: abortController.signal,
        })
        const data = await getMemoryExportResponse(response)
        if (cancelled || !data) return

        if (response.status === 202 && data.jobStatusUrl) {
          setIsWaitingForActiveExport(true)
          setIsCheckingActiveExport(false)
          const completedExport = await pollMemoryExportJob(data.jobStatusUrl, Date.now(), abortController.signal)
          if (!cancelled && completedExport?.state === 'success' && completedExport.downloadExportUrl) {
            setReadyExportUrl(completedExport.downloadExportUrl)
          }
        } else if (response.status > 399 || data.error || data.state === 'error') {
          throw new Error(data.error)
        } else if (data.state === 'success' && data.downloadExportUrl) {
          setReadyExportUrl(data.downloadExportUrl)
        }
      } catch (error) {
        if (!cancelled && !isAbortError(error)) {
          setNotification(notificationForError(error, MEMORY_EXPORT_STATUS_ERROR_MESSAGE))
        }
      } finally {
        if (!cancelled) {
          setIsCheckingActiveExport(false)
          setIsWaitingForActiveExport(false)
        }
      }
    }

    void checkActiveExport()

    return () => {
      cancelled = true
      abortController.abort()
    }
  }, [isOpen, memoryExportUrl])

  const resetDialogState = () => {
    dialogSessionIdRef.current += 1
    requestAbortControllerRef.current?.abort()
    requestAbortControllerRef.current = null
    setNotification(null)
    setReadyExportUrl(null)
    setIsCreatingExport(false)
    setIsCheckingActiveExport(false)
    setIsWaitingForActiveExport(false)
  }

  const closeDialog = () => {
    resetDialogState()
    onClose()
  }

  const requestExport = async (): Promise<void> => {
    if (!memoryExportUrl || isCreatingExport || isWaitingForActiveExport) return

    const currentDialogSessionId = dialogSessionIdRef.current
    const currentRequestId = requestIdRef.current + 1
    requestIdRef.current = currentRequestId
    const abortController = new AbortController()
    requestAbortControllerRef.current = abortController
    const canUpdateDialog = () => dialogSessionIdRef.current === currentDialogSessionId
    const isLatestRequest = () => requestIdRef.current === currentRequestId

    setIsCreatingExport(true)
    setNotification(null)
    try {
      const response = await verifiedFetch(memoryExportUrl, {method: 'POST', signal: abortController.signal})
      const data = (await response.json()) as MemoryExportResponse
      if (!canUpdateDialog()) return
      if (data.error) throw new Error(data.error)
      if (!data.jobStatusUrl) throw new Error('Missing export job data')

      const completedExport = await pollMemoryExportJob(data.jobStatusUrl, Date.now(), abortController.signal)
      if (!canUpdateDialog()) return
      const downloadExportUrl = completedExport?.downloadExportUrl || data.downloadExportUrl
      if (!downloadExportUrl) throw new Error('Missing export download URL')

      downloadMemoryExport(downloadExportUrl)
      closeDialog()
    } catch (error) {
      if (canUpdateDialog() && !isAbortError(error)) {
        setNotification(notificationForError(error, MEMORY_EXPORT_GENERATION_ERROR_MESSAGE))
      }
    } finally {
      if (requestAbortControllerRef.current === abortController) {
        requestAbortControllerRef.current = null
      }
      if (isLatestRequest()) {
        setIsCreatingExport(false)
      }
    }
  }

  const downloadReadyExport = () => {
    if (!readyExportUrl) return

    downloadMemoryExport(readyExportUrl)
    closeDialog()
  }

  const confirmDownload = () => {
    if (readyExportUrl) {
      downloadReadyExport()
    } else {
      void requestExport()
    }
  }

  if (!isOpen) return null

  const exportDescription = targetUserLogin
    ? `This will download user-scoped Copilot memories for ${targetUserLogin} that are billed to ${entityName}.`
    : `This will download user-scoped Copilot memories for all users with Copilot seats billed to ${entityName}.`

  return (
    <Dialog title="Download user memories?" onClose={closeDialog} data-testid="copilot-memory-exports-dialog">
      <p>{exportDescription}</p>
      <p>
        By clicking Download memories, you confirm you have permission to access this information on behalf of users in
        this {entityType}.
      </p>
      {notification && (
        <Banner
          variant={notification.variant}
          title={
            notification.variant === 'warning' ? 'Memory export is taking longer than expected' : 'Memory export failed'
          }
          hideTitle
          description={notification.message}
          data-testid="copilot-memory-exports-notification"
        />
      )}
      <Dialog.Footer>
        <Button type="button" onClick={closeDialog} disabled={isCreatingExport}>
          Cancel
        </Button>
        <Button
          type="button"
          onClick={confirmDownload}
          disabled={!memoryExportUrl || isCheckingActiveExport || isGeneratingExport}
          leadingVisual={isConfirmButtonBusy ? undefined : DownloadIcon}
          aria-busy={isConfirmButtonBusy}
          data-testid="copilot-memory-exports-confirm-button"
        >
          {isConfirmButtonBusy ? (
            <>
              <Spinner size="small" className="mr-2" srText={null} />
              {confirmButtonText}
            </>
          ) : (
            confirmButtonText
          )}
        </Button>
      </Dialog.Footer>
    </Dialog>
  )
}
